{
  "title": "Monthly Rainfall Summary",
  "body": "<article>
  <figure>
    <ml-embed ref="@tool:3fa9c21:out"></ml-embed>
    <figcaption>Figure: Monthly rainfall for the year.</figcaption>
  </figure>
  <div id="summary"></div>
</article>",
  "css": "article { font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; color: #1a1a2e; max-width: 720px; margin: 0 auto; }
figure { margin: 0 0 20px; text-align: center; }
figcaption { color: #5a5a72; font-size: 0.9rem; margin-top: 10px; }
#summary { background: #f4f8ff; border: 1px solid #d7e6ff; border-radius: 14px; padding: 18px 20px; }
#summary h3 { margin: 0 0 10px; font-size: 1.05rem; }
#summary p { margin: 6px 0; }",
  "scripts": [
    "const csv = ml.dereference("@tool:7be01d4:out");
const lines = csv.trim().split(/\r?\n/);
const rows = lines.slice(1).map(line => {
  const parts = line.split(",");
  return { month: parts[0].trim(), mm: Number(parts[1]) };
});
const sorted = rows.slice().sort((a, b) => b.mm - a.mm);
const top3 = sorted.slice(0, 3);
const total = rows.reduce((sum, row) => sum + row.mm, 0);
const summary = root.byId.summary;
summary.children = [
  { tag: "h3", attrs: {}, text: "Three wettest months" },
  { tag: "p", attrs: {}, text: top3.map(row => `${row.month}: ${row.mm} mm`).join(" · ") },
  { tag: "p", attrs: {}, text: `Total annual rainfall: ${total} mm` }
];"
  ]
}
```
